I think this works (copy paste to notepad, save as .js file and add as a plugin). Change the SEs to what you like. But yeah, there's cases like if you change the position of the message box from like bottom to middle, then that doesContinue no longer counts, so it counts it as opening (edit: actually closing) instead of continuing. Though of course it actually does close and open in that situation.
const _myEdit1_WindowMessage_newPage = Window_Message.prototype.newPage;
Window_Message.prototype.newPage = function(textState) {
_myEdit1_WindowMessage_newPage.call(this, textState);
if (this.isClosed()){
AudioManager.playSe({
name: 'Bell1',
volume: 100,
pitch: 100,
pan: 0
});
} else {
AudioManager.playSe({
name: 'Buzzer1',
volume: 100,
pitch: 100,
pan: 0
});
}
};
const _myEdit1_WindowMessage_update = Window_Message.prototype.update;
Window_Message.prototype.update = function() {
if (this.isOpen() && this.isClosing() && !this.doesContinue()) {
AudioManager.playSe({
name: 'Cow',
volume: 100,
pitch: 100,
pan: 0
});
}
_myEdit1_WindowMessage_update.call(this);
};

