It almost works, but it plays all 3 sound effects one after the other upon a new message box appearing (whether from being newly opened or from progressing to the next box), instead of them each playing at their respective moment. That's the best I can explain it, does it make sense?

If you want transparent not to play it, I think you can add checks for the backgrounds like below.
But these edits I've made don't take into account if you keep mixing different bg types in succession, because then the message window will keep opening and closing I think. You'd need heavier edits to account for all cases.
const _myEdit1_WindowMessage_newPage = Window_Message.prototype.newPage;
Window_Message.prototype.newPage = function(textState) {
_myEdit1_WindowMessage_newPage.call(this, textState);
if (this.isClosed()) {
if ($gameMessage.background() !== 2) {
AudioManager.playSe({
name: 'Bell1',
volume: 100,
pitch: 100,
pan: 0
});
}
} else {
AudioManager.playSe({
name: 'Buzzer1',
volume: 100,
pitch: 100,
pan: 0
});
}
};
const _myEdit1_WindowMessage_update = Window_Message.prototype.update;
Window_Message.prototype.update = function() {
if (this.isOpen() && this.isClosing() && !this.doesContinue() && this._background !== 2) {
AudioManager.playSe({
name: 'Cow',
volume: 100,
pitch: 100,
pan: 0
});
}
_myEdit1_WindowMessage_update.call(this);
};

